import {
  Group,
  Mesh,
  PlaneGeometry,
  IcosahedronGeometry,
  DirectionalLight,
  PointLight,
  Color,
  Texture,
  DoubleSide,
  MeshStandardNodeMaterial,
  MeshPhysicalNodeMaterial,
  MeshBasicNodeMaterial,
} from 'three/webgpu';
import {
  texture,
  uv,
  vec2,
  vec3,
  float,
  mix,
  smoothstep,
  length,
  positionLocal,
  normalLocal,
  uniform,
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'features-ornamental-divider';

  // ---- placeholder textures swapped in when async load resolves ----
  const mapTexPlaceholder = new Texture();
  const depthTexPlaceholder = new Texture();
  const mapNode = texture(mapTexPlaceholder, uv());
  const depthNode = texture(depthTexPlaceholder, uv());

  const imageUrl = config.imageUrl;
  const depthMapUrl = config.depthMapUrl;

  if (imageUrl) {
    ctx.textureLoader
      .loadTexture(imageUrl)
      .then((tex) => {
        mapNode.value = tex;
      })
      .catch(() => {});
  }
  if (depthMapUrl) {
    ctx.textureLoader
      .loadTexture(depthMapUrl)
      .then((tex) => {
        depthNode.value = tex;
      })
      .catch(() => {});
  }

  // ---- thin machined rule ----
  const ruleWidth = 3.0;
  const ruleHeight = 0.05;
  const ruleGeo = new PlaneGeometry(ruleWidth, ruleHeight, 64, 8);

  const displaceStrength = uniform(0.015);
  const ruleMat = new MeshStandardNodeMaterial();
  ruleMat.side = DoubleSide;
  ruleMat.metalness = 0.5;
  ruleMat.roughness = 0.52;
  ruleMat.color = new Color(colors.paper);

  const paperColor = new Color(colors.paper);
  const baseColorNode = vec3(paperColor.r, paperColor.g, paperColor.b);
  ruleMat.colorNode = mix(baseColorNode, mapNode.rgb, float(0.22));
  ruleMat.positionNode = positionLocal.add(
    normalLocal.mul(depthNode.r.sub(0.5).mul(displaceStrength))
  );

  const rule = new Mesh(ruleGeo, ruleMat);
  rule.position.set(0, 0, 0);
  group.add(rule);

  // ---- center jewel (foreground accent) ----
  const jewelGeo = new IcosahedronGeometry(0.09, 2);
  const jewelMat = new MeshPhysicalNodeMaterial();
  const accentColor = new Color(colors.accent);
  jewelMat.color = accentColor;
  jewelMat.emissive = accentColor;
  jewelMat.emissiveIntensity = 1.1;
  jewelMat.metalness = 0.3;
  jewelMat.roughness = 0.22;
  jewelMat.clearcoat = 0.2;
  jewelMat.clearcoatRoughness = 0.15;
  jewelMat.transmission = 0.35;
  jewelMat.ior = 1.5;
  jewelMat.thickness = 0.05;

  const jewel = new Mesh(jewelGeo, jewelMat);
  jewel.position.set(0, 0, 0.035);
  group.add(jewel);

  // ---- radial contact shadow grounding the jewel/rule ----
  const shadowGeo = new PlaneGeometry(0.55, 0.55, 1, 1);
  const shadowMat = new MeshBasicNodeMaterial();
  shadowMat.transparent = true;
  shadowMat.depthWrite = false;
  const suv = uv().sub(vec2(0.5, 0.5));
  const dist = length(suv);
  const falloff = smoothstep(0.5, 0.0, dist);
  shadowMat.colorNode = vec3(0.0, 0.0, 0.0);
  shadowMat.opacityNode = falloff.mul(0.45);
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -0.1, -0.02);
  group.add(shadow);

  // ---- node-local rim + fill lights (accent hue) ----
  const rim = new DirectionalLight(accentColor, 0.75);
  rim.position.set(-1.2, 0.6, 1.0);
  group.add(rim);

  const fillPoint = new PointLight(new Color(colors.paper), 0.5, 2.0);
  fillPoint.position.set(0.8, 0.4, 0.6);
  group.add(fillPoint);

  // ---- mandated subtle parallax on the tessellated plane ----
  const parallaxResult = ctx.primitives['parallax-scroll']
    ? ctx.primitives['parallax-scroll'](rule, { strength: 0.05, trigger: 'scroll' })
    : null;

  // ---- entrance: weighted settle ----
  const timelines = [];
  group.scale.set(0.001, 0.001, 0.001);
  const introTl = gsap.timeline();
  introTl
    .to(group.scale, { x: 1.04, y: 1.04, z: 1.04, duration: 0.5, ease: 'power3.out' })
    .to(group.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'power4.out' });
  timelines.push(introTl);

  // ---- interactions ----
  const baseY = group.position.y;

  function hoverIn() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY + 0.15, duration: 0.5, ease: 'power3.out' });
    tl.to(group.scale, { x: 1.03, y: 1.03, z: 1.03, duration: 0.5, ease: 'power3.out' }, 0);
    timelines.push(tl);
  }

  function hoverOut() {
    const tl = gsap.timeline();
    tl.to(group.position, { y: baseY, duration: 0.6, ease: 'power2.out' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.6, ease: 'power2.out' });
    timelines.push(tl);
  }

  function onClick() {
    const tl = gsap.timeline();
    tl.to(group.scale, { x: 0.97, y: 0.97, z: 0.97, duration: 0.12, ease: 'back.out(2)' });
    tl.to(group.scale, { x: 1, y: 1, z: 1, duration: 0.3, ease: 'power4.out' });
    timelines.push(tl);
    ctx.emit('hub-features.select', { nodeId: config.id ?? 'features-divider' });
  }

  group.userData.handlers = {
    onPointerOver: hoverIn,
    onPointerOut: hoverOut,
    onClick: onClick,
  };

  group.userData.cleanup = function cleanup() {
    for (const tl of timelines) tl.kill();
    if (parallaxResult && parallaxResult.cleanup) parallaxResult.cleanup();

    ruleGeo.dispose();
    ruleMat.dispose();
    jewelGeo.dispose();
    jewelMat.dispose();
    shadowGeo.dispose();
    shadowMat.dispose();

    mapTexPlaceholder.dispose();
    depthTexPlaceholder.dispose();
    if (mapNode.value && mapNode.value !== mapTexPlaceholder) mapNode.value.dispose?.();
    if (depthNode.value && depthNode.value !== depthTexPlaceholder) depthNode.value.dispose?.();
  };

  return group;
}
